\[
\begin{split}
gcd(b, a) &= gcd(b_0, a_0)\\
&
\class{steps}{\cssId{step0}{= gcd(a_0, r_0) = gcd(b_1, a_1)}}
\\
&
\class{steps}{\cssId{step1}{= gcd(a_1, r_1) = gcd(b_2, a_2)}}
\\
&
\class{steps}{\cssId{step2}{= \ldots}}
\\
&
\class{steps}{\cssId{step3}{= gcd(a_{n}, r_{n}) = gcd(a_n, 0) = \abs{a_n}.}}
\end{split}
\]
